  function lxSourcePresentation(lecture) {
    const seen = new Set(), references = [];
    const add = value => {
      const t = String(value || '').replace(/^\s*[-*]\s*/, '').trim();
      if (!t || /^(none|n\/a|unknown|not provided)$/i.test(t)) return;
      const key = t.toLocaleLowerCase().replace(/[.。]+$/, '').replace(/\s+/g, ' ');
      if (!seen.has(key)) { seen.add(key); references.push(t); }
    };
    add(lecture.source);
    const sections = (lecture.sections || []).map(sec => {
      const body = String(sec.body || '');
      const kept = [];
      for (const line of body.split(/\r?\n/)) {
        const m = line.match(/^\s*(?:\*\*)?\s*(?:SOURCE|SOURCES|REFERENCE|REFERENCES)(?:\*\*)?\s*:\s*(?:\*\*)?\s*(.+?)\s*$/i);
        if (m) add(m[1]);
        else kept.push(line);
      }
      return {...sec, body: kept.join('\n').replace(/^\s*\n/, '').trimEnd()};
    });
    return { sections, references };
  }
  function bsaRevisionExcerpt(md){
    const lines=String(md||'').split('\n').filter(x=>!/^\s*(?:SOURCE:|Sources?\s*:)/i.test(x.trim()));
    const clean=lines.join(' ').replace(/\|/g,' ').replace(/[#*`_>]/g,'').replace(/\s+/g,' ').trim();
    if(!clean)return 'No summary excerpt available; consult the complete lecture.';
    const max=230;
    if(clean.length<=max)return clean;
    const cut=clean.slice(0,max).replace(/\s+\S*$/,'').trim();
    return (cut||clean.slice(0,max))+'… (excerpt; full text is in the complete lecture)';
  }
