        L.push("\n=== PROBLEMS FROM \"" + s.title + "\"" + (missed.length ? " THAT THE STUDENT GOT WRONG" : "") + " ===");
        for (const p of show) L.push("Problem " + p.no + " (" + (p.subtopic || "general") + "): " + psPlain(p.problem).slice(0, 900) + "\nAnswer: " + psPlain(p.answer).slice(0, 400) + (p.trap ? "\nTrap: " + psPlain(p.trap).slice(0, 300) : ""));
