    const keys = /"(flashcards|topics|mistakes|quizzes|problemSets|lectures|drills|grading|textbook)"\s*:/;
    const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/);
    const cand = fence ? fence[1] : ((t.match(/[[{][\s\S]*[\]}]/) || [])[0] || "");
    if (!cand || !keys.test(cand)) return "";
