    if(!entry)return h('section',{className:'panel bsa-topic-master-panel'},h('h2',null,'Topic Mastery Hub'),h('p',{className:'muted'},'Add roadmap topics to connect your learning evidence.'));
    const c=bsaTopicConnections(entry.s,entry.t.id);
    const stat=smartTopicStats(entry.s).find(x=>x.topic&&x.topic.id===entry.t.id);
    const canMeasure=!!(stat && stat.signals && stat.signals.overall && stat.signals.overall.weight>0);
