  class ScreenBoundary extends React.Component {
    constructor(props){super(props);this.state={error:null};}
    static getDerivedStateFromError(error){return {error};}
    componentDidCatch(error){console.error('Study Desk screen failed:',this.props.route,error);}
    componentDidUpdate(prev){if(prev.route!==this.props.route && this.state.error)this.setState({error:null});}
    render(){if(!this.state.error)return this.props.children;
      return h('section',{className:'bsa-screen-recovery',role:'alert'},
        h('div',{className:'bsa-screen-recovery-icon','aria-hidden':true},'↻'),
        h('h2',null,'This section needs a fresh start'),
        h('p',null,'Your existing study data has not been cleared. Other sections can still open.'),
        h('p',{className:'muted small'},'Section: '+this.props.route),
        h('div',{className:'bsa-screen-recovery-actions'},
          h('button',{className:'btn primary',onClick:()=>this.setState({error:null})},'Try again'),
          h('button',{className:'btn',onClick:this.props.onHome},'Back to Today'),
          h('button',{className:'btn',onClick:()=>bsaDownloadUnifiedBackup(msg=>alert(msg))},'Back up study data'))
      );
    }
  }
  function StartupDataRecovery(){
    const problem=window.__BSA_UNREADABLE_DATA__;
    const exportRaw=()=>{
      const blob=new Blob([problem.raw],{type:'application/json;charset=utf-8'});
      const url=URL.createObjectURL(blob), a=document.createElement('a');
      a.href=url;a.download='BSA-RECOVERY-original-data-'+new Date().toISOString().slice(0,10)+'.json';a.click();
      setTimeout(()=>URL.revokeObjectURL(url),5000);
    };
    const reset=()=>{
      if(window.prompt('This erases the unreadable local study data. FIRST download the original recovery file. Type REPLACE to continue:')!=='REPLACE')return;
      try{localStorage.removeItem(STORE_KEY);location.reload()}catch(error){alert('Could not reset this browser: '+String(error&&error.message||error));}
    };
    return h('main',{className:'dashboard-recovery bsa-startup-recovery',role:'alert'},
      h('h1',null,'Your saved study data needs recovery'),
      h('p',null,'The app found study data it could not safely read. To protect your records, it has NOT replaced that data with a blank dashboard.'),
      h('p',{className:'muted small'},problem.reason),
      h('div',{className:'bsa-screen-recovery-actions'},
        h('button',{className:'btn primary',onClick:exportRaw},'Download original data file'),
        h('button',{className:'btn',onClick:()=>location.reload()},'Try opening again')),
      h('details',null,h('summary',null,'Open a clean dashboard only after preserving the original data'),
        h('p',null,'This discards the unreadable local copy. Restore a known-good study backup through Import & Export afterward.'),
        h('button',{className:'btn danger',onClick:reset},'Replace unreadable local copy')));
  }
